<?php
namespace App\Http\Controllers; use App\Models\{Plan,Project}; use App\Services\AuditService; use Illuminate\Http\Request;
class PlanController extends Controller { private function data(Request $r){return $r->validate(['project_id'=>'required|exists:projects,id','title'=>'required|max:180','type'=>'required|in:TAREA,HITO,IDEA,FUTURO','status'=>'required|in:PENDIENTE,EN_PROGRESO,COMPLETADO,PAUSADO,CANCELADO','weight'=>'required|integer|min:1|max:100','due_date'=>'nullable|date','notes'=>'nullable']);} public function index(){return view('plans.index',['items'=>Plan::with('project')->orderByRaw("CASE status WHEN 'EN_PROGRESO' THEN 1 WHEN 'PENDIENTE' THEN 2 ELSE 3 END")->latest()->get()]);} public function create(){return view('plans.form',['item'=>new Plan,'projects'=>Project::orderBy('name')->get()]);} public function store(Request $r){$x=Plan::create($this->data($r));AuditService::log('PLAN_CREATED',$x->title,$x);return redirect()->route('plans.index')->with('ok','Planificación guardada.');} public function edit(Plan $plan){return view('plans.form',['item'=>$plan,'projects'=>Project::orderBy('name')->get()]);} public function update(Request $r,Plan $plan){$plan->update($this->data($r));AuditService::log('PLAN_UPDATED',$plan->title,$plan);return redirect()->route('plans.index')->with('ok','Planificación actualizada.');} public function destroy(Plan $plan){$title=$plan->title;$plan->delete();AuditService::log('PLAN_DELETED',$title);return redirect()->route('plans.index')->with('ok','Elemento eliminado.');}}
